package com.silverroom.camera;
import org.json.*;
import java.text.*;
import java.util.*;

/** Labels always come from this photograph, not the currently selected lens/film. */
public final class PrintMetadata {
    public final String date,focal,film,exifDate,camera,lens,exposure;
    public PrintMetadata(String id,JSONObject j){String exif="",day="";long time=j.optLong("captured_at",0);if(time>0){SimpleDateFormat format=new SimpleDateFormat("yyyy:MM:dd HH:mm:ss",Locale.US);format.setTimeZone(new SimpleTimeZone(j.optInt("capture_offset_minutes",0)*60000,"capture"));exif=format.format(new Date(time));day=exif.substring(0,10).replace(':','.');}else{String source=j.optString("source_datetime","");if(validDate(source)){exif=source;day=source.substring(0,10).replace(':','.');}else if(!j.optBoolean("imported",false)&&!j.optString("lens","").contains("导入")&&NegativeStore.valid(id)){String candidate=id.substring(0,4)+":"+id.substring(4,6)+":"+id.substring(6,8)+" "+id.substring(9,11)+":"+id.substring(11,13)+":"+id.substring(13,15);if(validDate(candidate)){exif=candidate;day=candidate.substring(0,10).replace(':','.');}}}JSONObject supplement=j.optJSONObject("annotations");if(day.isEmpty()&&supplement!=null&&validDate(supplement.optString("date")))day="补填 · "+supplement.optString("date").substring(0,10).replace(':','.');date=day;exifDate=exif;JSONObject capture=j.optJSONObject("capture");if(capture==null)capture=j.optJSONObject("source_capture");float mm=capture==null?0:(float)capture.optDouble("mm",0);if(mm<=0){java.util.regex.Matcher m=java.util.regex.Pattern.compile("^(\\d+(?:\\.\\d+)?)mm").matcher(j.optString("lens",""));if(m.find())try{mm=Float.parseFloat(m.group(1));}catch(Exception ignored){}}focal=mm>0&&Float.isFinite(mm)?ZoomScale.label(mm)+"mm":"";int stock=j.optInt("stock",-1);film=FilmCatalog.valid(stock)?FilmCatalog.NAMES[stock]:"";JSONObject nativeData=j.optJSONObject("capture");if(nativeData==null)nativeData=j.optJSONObject("source_capture");if(nativeData==null)nativeData=new JSONObject();JSONObject annotations=j.optJSONObject("annotations");if(annotations==null)annotations=new JSONObject();String body=(nativeData.optString("make")+" "+nativeData.optString("model")).trim();camera=body.isEmpty()&&!annotations.optString("camera").isEmpty()?"补填 · "+annotations.optString("camera"):body;double real=nativeData.optDouble("focal_mm",0);lens=!nativeData.optString("lens_model").isEmpty()?nativeData.optString("lens_model"):real>0?String.format(Locale.US,"%.2fmm",real):annotations.optString("lens").isEmpty()?"":"补填 · "+annotations.optString("lens");String detail="";int iso=nativeData.optInt("iso",0);double aperture=nativeData.optDouble("aperture",0);long ns=nativeData.optLong("exposure_ns",0);if(iso>0)detail="ISO "+iso;if(aperture>0)detail+=(detail.isEmpty()?"":" · ")+String.format(Locale.US,"f/%.1f",aperture);if(ns>0)detail+=(detail.isEmpty()?"":" · ")+MeterMath.time(ns/1e9);if(detail.isEmpty()){String supplementary="";if(annotations.has("iso"))supplementary="ISO "+annotations.optString("iso");if(annotations.has("aperture"))supplementary+=(supplementary.isEmpty()?"":" · ")+"f/"+annotations.optString("aperture");if(annotations.has("seconds"))try{supplementary+=(supplementary.isEmpty()?"":" · ")+MeterMath.time(Double.parseDouble(annotations.optString("seconds")));}catch(Exception ignored){}if(!supplementary.isEmpty())detail="补填 · "+supplementary;}exposure=detail;}
    static boolean validDate(String value){if(value==null||!value.matches("\\d{4}:\\d{2}:\\d{2} \\d{2}:\\d{2}:\\d{2}"))return false;try{SimpleDateFormat format=new SimpleDateFormat("yyyy:MM:dd HH:mm:ss",Locale.US);format.setLenient(false);format.parse(value);return true;}catch(ParseException e){return false;}}
    public String[] captions(PrintOptions options){if(options.style==0)return new String[0];List<String> lines=new ArrayList<>();if(options.date&&!date.isEmpty())lines.add(date);String detail=(options.focal?focal:"");if(options.film&&!film.isEmpty())detail+=(detail.isEmpty()?"":"  /  ")+film;if(!detail.isEmpty())lines.add(detail);if(options.camera&&!camera.isEmpty())lines.add(camera);if(options.lens&&!lens.isEmpty())lines.add(lens);if(options.exposure&&!exposure.isEmpty())lines.add(exposure);return lines.toArray(new String[0]);}
}
